changeSet.sql:
ALTER TABLE public.tenant_organization
    ADD COLUMN retailer_type_code character varying(64);
COMMENT ON COLUMN public.tenant_organization.retailer_type_code IS
    'Shop pack when site_type is RETAIL: GAS_STATION, GAS_STATION_ENT, LIQUOR_STORE, DUNKIN_DONUTS, or SEVEN_ELEVEN.';
COMMENT ON COLUMN public.tenant_organization.site_type IS
    'Product archetype for the tenant site: EVENT_ORG | SPORTS_TEAM | MUSIC_BAND | CHURCH_ORG | PERSONAL_PROFILE | HYBRID | RETAIL. Shop packs live in retailer_type_code.';
